INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (960, 'EPL Excellence Scholarships (UCLouvain)', 'École polytechnique de Louvain (EPL), UCLouvain', 'Belgium', 'Full Tuition Waiver', 0, 'Apply for master''s admission at UCLouvain and submit the EPL Excellence Scholarships form by 31 March (non-EU nationals) or 31 May (EU nationals); applications are reviewed in parallel with admissions on a rolling basis, so early application is encouraged. The scheme was newly launched for 2026-2027; the next non-EU deadline is 31 March 2027.', '2027-03-31', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Master's programmes at the Louvain School of Engineering (EPL) - engineering, computer science and data-science programmes"]$j$, '[]', 3.2, NULL, false, true, $desc$The EPL Excellence Scholarships are the new merit scholarships of the Louvain School of Engineering (École polytechnique de Louvain, EPL) at UCLouvain, launched to attract outstanding engineering and computer-science students from around the world to a master's degree at UCLouvain (Louvain-la-Neuve and Charleroi). They are open to international applicants admitted to an EPL master's programme - engineering, computer science and data-science programmes included - and selection is primarily on academic excellence. The scholarship covers the full UCLouvain tuition fee for the duration of the master's programme (two years), provided the student's first-year performance is satisfactory - all courses credited with a minimum GPA of 13/20. Selection runs in parallel with admissions and weighs the applicant's academic performance (a minimum GPA of 3.2/4, equivalent to about 80% and a top-10% ranking in previous years), the academic reputation of the bachelor's institution, and the overall quality of the file (research experience and publications, relevant work or internship experience, teaching experience, awards and competitions). Candidates apply for admission as international students - the only extra document is a professor's letter of recommendation added to the admission application - and then submit the EPL Excellence form by 31 March as non-EU nationals (31 May for EU nationals); files are reviewed on a rolling basis and successful candidates are notified shortly after their admission is confirmed. Note that this faculty award is an exception to UCLouvain's general position of not granting scholarships to international bachelor's and master's students - it is specific to EPL master's programmes.$desc$, $req$Applicants must meet the admission requirements of an eligible EPL master's programme, apply successfully for admission as an international student, and include a professor's letter of recommendation in the online admission application; the subsequent EPL Excellence Scholarships form must be filed by 31 March (non-EU) or 31 May (EU). Awards are made primarily on academic excellence: the official selection criteria name a minimum GPA of 3.2/4 (about 80%; top 10% in previous cohorts), the standing of the bachelor's institution, and the overall file quality (research experience/publications, relevant professional or internship experience, teaching experience, awards and competitions). The 3.2/4 figure is a single published minimum on an unambiguous scale and is therefore recorded as min_gpa (it functions as a selection threshold rather than a hard eligibility gate). Renewal into the second year requires all first-year courses credited with a minimum GPA of 13/20, and the grant is conditional on completing enrolment at UCLouvain. The scholarship page publishes no IELTS figure (language requirements follow the chosen master's admission rules), so min_ielts is not recorded.$req$, 'https://uclouvain.be/fr/facultes/epl/epl-excellence-scholarships-masters-programme', 'https://uclouvain.be/fr/facultes/epl/epl-excellence-scholarships-masters-programme', 'https://www.uclouvain.be/en/enrolment/proceed-with-your-application', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 15) from the Louvain School of Engineering's official EPL Excellence Scholarships page fetched the same day (newly launched scheme, first cycle 2026-2027 with an exceptional EU deadline extension to 21 June and July notification; full UCLouvain tuition fee covered for the two-year master conditional on first-year performance - all courses credited, minimum GPA 13/20; international applicants to EPL engineering, computer science and data-science masters; selection primarily on academic excellence with a published minimum GPA of 3.2/4, ~80%, top-10% ranking; application = international admission application with a professor's recommendation letter + EPL form by 31 March for non-EU and 31 May for EU nationals; rolling review parallel to admissions). This record was spotted during cleanup pass 108, which retired the invented university-wide 'UCLouvain International Excellence Scholarship' (479): the university's FAQ says UCLouvain grants no scholarships to international bachelor's/master's students, and this faculty-level (EPL) award is the genuine, narrower exception, recorded here as a master's-only award. award_amount is NULL (a 100% tuition waiver whose euro value depends on the programme's fee), currency EUR / period 'year' / basis 'variable' per the percentage-waiver convention. deadline_date 2027-03-31 is the next annual non-EU form deadline; status 'upcoming' because the fetched page still describes the launch cycle and the 2027-2028 admission round was not shown as open. min_gpa 3.2 stored as the single published selection minimum (4.0 scale); min_ielts NULL. university_id set to the existing UCLouvain record (112) and a university_scholarships row added.$note$, 112, NULL, 'EUR', 'year', 'variable', NULL, '100% waiver of the UCLouvain tuition fee for the full master''s duration (two years), subject to satisfactory first-year results', 'The full tuition fee is waived for two years, provided all first-year courses are credited with a minimum GPA of 13/20; no living allowance is included.', 'The scholarship publishes no IELTS cutoff; language requirements are those of the chosen EPL master''s programme (see UCLouvain international-student admission rules).', $j$["Admission application as an international student to an eligible EPL master's programme", "Letter of recommendation from a professor included in the online admission application", "EPL Excellence Scholarships form submitted by 31 March (non-EU) or 31 May (EU)", "Evidence of academic excellence (transcripts showing at least the equivalent of GPA 3.2/4) and any research/work experience, awards or publications"]$j$, NULL, NULL, $json$[{"cycle": "2027-2028 entry (expected annual dates)", "deadline_non_eu": "2027-03-31", "deadline_eu": "2027-05-31", "status": "upcoming"}, {"pattern": "Annual: admission application plus EPL Excellence form by 31 March (non-EU) or 31 May (EU); rolling selection in parallel with admissions, decisions shortly after admission confirmation"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (957, 'Inspiring the Outstanding Scholarship (KU Leuven)', 'KU Leuven International Scholarship Fund', 'Belgium', 'Full Funding', 0, 'For 2027-2028 entry: applications opened 15 October 2026 and close 15 January 2027, 23.59 CET - one joint application with the Master Mind Scholarship (complete master''s application with the KU Leuven Scholarships & Master Mind Candidacy Form as an annexe, plus online candidacy registration). The scholarships cannot be applied for separately.', '2027-01-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Eligible KU Leuven master's programmes (per the published 2027-2028 eligible-programmes list; bridging and distance-learning programmes are excluded)"]$j$, '[]', NULL, NULL, false, true, $desc$The Inspiring the Outstanding Scholarship is KU Leuven's own excellence award for outstanding international master's students, financed by the KU Leuven International Scholarship Fund - the university's donation fund in which the global KU Leuven community supports talented students regardless of financial background. Recipients receive a full tuition fee waiver (only an annual administration fee of about €140 remains payable) plus an allowance of €13,200 per academic year, for one academic year on a 60-ECTS master or up to two academic years on a 120-ECTS master; for 2027-2028 exactly one scholarship is available. It is applied for through a single joint procedure with the Flemish Government's Master Mind Scholarship: filing the complete master's application with the KU Leuven Scholarships & Master Mind Candidacy Form and registering the candidacy online by 15 January 2027 (23.59 CET) enters the applicant for this scholarship, Master Mind, and - where nationality matches - the KU Leuven ASEAN, Africa and Central and South America scholarships at the same time; the awards cannot be applied for separately. Eligibility mirrors Master Mind: all nationalities, a high GPA, and previous degrees obtained outside Flanders, with students already enrolled at a Flemish institution excluded. It cannot be combined with another full scholarship from KU Leuven, the Belgian national or regional governments, or the European Commission. The larger allowance (€13,200 vs Master Mind's €10,750) and the genuine full fee waiver make this the most generous - and, with a single place, the most selective - of KU Leuven's joint-application awards.$desc$, $req$All nationalities are eligible. The student must show a high level of academic performance and potential (excellent results reflected in a high GPA on the transcript), and previous degrees must have been obtained at a higher-education institution outside Flanders (credit mobility in Flanders does not disqualify). Students already enrolled at a Flemish higher-education institution are ineligible (preparatory-programme exception for a September 2027 master's start), and the scholarship cannot be combined with another full scholarship offered by KU Leuven, the Belgian national or regional governments, or the European Commission. The master's must appear on KU Leuven's eligible-programmes list; bridging and distance-learning programmes are out of scope. English: regardless of the programme's own minimum, non-native speakers must demonstrate a good command of English (test taken before the 15 January deadline, results may follow; exemptions for prior English-taught degrees in Australia, English-speaking Canada, Ireland, New Zealand, the UK and the USA). No numeric GPA cutoff and no cycle-fixed scholarship-level IELTS number are published, so min_gpa/min_ielts are not recorded (KU Leuven's general minima are IELTS 6.5/TOEFL 79, and the joint Master Mind rules have previously set IELTS 7.0/TOEFL 94 at Flemish level).$req$, 'https://www.kuleuven.be/scholarships/year/2027-2028/inspiring-the-outstanding-scholarship', 'https://www.kuleuven.be/scholarships/year/2027-2028/inspiring-the-outstanding-scholarship', 'https://www.kuleuven.be/english/apply', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 15) from KU Leuven's official 'The Inspiring the Outstanding Scholarship' 2027-2028 page fetched the same day (sponsor: KU Leuven International Scholarship Fund; full tuition fee waiver with only an approx. €140 annual administration fee payable; €13,200 per academic year for a maximum of two academic years; one scholarship available for 2027-2028; duration one year on a 60-ECTS master and two on a 120-ECTS master; all nationalities eligible; prior degrees outside Flanders; current Flemish enrolment disqualifying; no combination with another full KU Leuven/Belgian/EC scholarship; single joint application procedure shared with Master Mind and the regional KU Leuven scholarships, open 15 October 2026 and closing 15 January 2027 at 23.59 CET with the candidacy-form annexe and online registration). Recorded as a separate award from the Master Mind Scholarship at KU Leuven (record 144) because the funder (KU Leuven's own donation fund vs the Flemish Ministry of Education and Training), the package (€13,200/year plus a true full fee waiver vs €10,750 with reduced EEA-tariff tuition) and the quota (1 vs 3) all differ, although both run through one application - the shared route is stated in the description. Award stored as a fixed €13,200/year. deadline_date 2027-01-15 is the live cycle closing with status 'open'; min_gpa/min_ielts NULL. university_id set to the existing KU Leuven record (48) and a university_scholarships row added.$note$, 48, 13200, 'EUR', 'year', 'fixed', NULL, '€13,200 allowance per academic year + full tuition fee waiver (only approx. €140 annual administration fee); 1 scholarship for 2027-2028', 'Tuition fees are fully waived for the scholarship duration (one academic year for a 60-ECTS master, two for a 120-ECTS master); an administration fee of about €140 per year remains payable.', 'Good command of English regardless of the programme minimum (test before 15 January, results may follow; exemptions for prior English-taught degrees in Australia, English-speaking Canada, Ireland, New Zealand, the UK or the USA). KU Leuven general minima: IELTS 6.5/TOEFL 79; prior joint-cycle Master Mind rules used IELTS 7.0/TOEFL 94.', $j$["Complete application file for an eligible KU Leuven master's by 15 January 2027, 23.59 CET, including the KU Leuven Scholarships & Master Mind Candidacy Form (document type 'Annexe')", "Registration of the scholarship candidacy via KU Leuven's online registration tool by the same deadline", "English proficiency test taken before the deadline (results may be submitted afterwards)"]$j$, NULL, NULL, $json$[{"cycle": "2027-2028 entry", "opens": "2026-10-15", "deadline": "2027-01-15", "status": "open"}, {"pattern": "Annual: one joint application with the Master Mind Scholarship - applications open mid-October, close 15 January (23.59 CET) for the following academic year"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (959, 'Science@Leuven Scholarship (KU Leuven Faculty of Science)', 'KU Leuven Faculty of Science (Science@Leuven Fund)', 'Belgium', 'Merit Grant (up to €12,000 per year)', 0, 'Apply via the KU Leuven Application Tool and register on the scholarship website before 15 February of the entry year; admitted candidates are ranked mid-to-late April (interviews for shortlisted candidates) and awards are announced at the beginning of May. Next deadline: 15 February 2027 for 2027-2028 entry.', '2027-02-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Eligible English-taught master's programmes of the KU Leuven Faculty of Science (programmes list on the scholarship website)"]$j$, '[]', NULL, 7.0, false, true, $desc$The Science@Leuven Scholarships are the long-running merit scholarships of KU Leuven's Faculty of Science and its alumni association Science@Leuven, awarded through the Science@Leuven Fund to motivated, talented international students admitted to one of the Faculty's eligible English-taught master's programmes. The scholarship can be up to €12,000 for one year - the Board of the Science@Leuven Fund decides the exact amount for each holder - and even the full €12,000 comes with the Faculty's own advice to bring extra money for living costs in Belgium. Most Faculty of Science masters are two-year programmes, and continuation into the second master year is conditional on outstanding first-year results. The selection is deliberately strict: applicants must never have studied or worked at KU Leuven before (current KU Leuven students are excluded), hold a bachelor's from a non-Belgian university giving access to the master, hold no master's or PhD yet, prove excellent study results (they are expected to reach at least Distinction at KU Leuven), prove a very strong knowledge of English at the C1-level minima below, show strong motivation, submit two reference letters from internationally renowned professors, and be willing to act as an ambassador for the programme and KU Leuven. Applications filed through the KU Leuven Application Tool and registered on the scholarship website before 15 February are considered: the programme's admission committee evaluates files through March, only admitted students enter the scholarship selection in April (with online interviews for the shortlist), and the Fund's board awards and notifies students at the beginning of May.$desc$, $req$All requirements on the official admission page must be met and proven ('Please do not apply if you do not meet all the requirements'): the applicant has not studied or worked at the University of Leuven before and is not a KU Leuven student; holds a bachelor degree from a non-Belgian university that gives access to the master programme applied for; has not yet acquired a master degree or a PhD when starting the programme; can prove excellent study results during former training (expected to obtain at least Distinction during studies at KU Leuven - a qualitative bar, so min_gpa is not recorded); can prove a very strong knowledge of English - TOEFL iBT minimum 94 overall (Reading 19, Listening 18, Speaking 19, Writing 21), IELTS Academic minimum 7.0 overall (Reading 6.5, Listening 6.0, Speaking 6.0, Writing 6.0), or Cambridge Advanced/Proficiency minimum 185 (reading 176, other components 169), with exemption only for a prior degree taught entirely in English in Australia, English-speaking Canada, Ireland, New Zealand, the UK or the USA; shows strong motivation; submits two reference letters from internationally renowned professors; and is willing to act as ambassador for the programme and KU Leuven. The scholarship-specific IELTS minimum of 7.0 overall is a single published figure and is stored as min_ielts.$req$, 'https://wet.kuleuven.be/english/scienceatleuvenscholarship', 'https://wet.kuleuven.be/english/scienceatleuvenscholarship', 'https://wet.kuleuven.be/apps/fund/new.php', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 15) from the KU Leuven Faculty of Science's official Science@Leuven Scholarships pages fetched the same day - landing page ('Application for academic year 2026-2027 is now closed'), Amount ('up to 12.000 Euro for 1 year'; board decides the exact amount; extra money advised even at the full amount; second year conditional on outstanding first-year results), Admission Requirements (the eight cumulative conditions quoted in the requirements field, including the never-at-Leuven rule, non-Belgian bachelor, no master/PhD held, excellent results, the English minima, two reference letters from internationally renowned professors and the ambassador commitment), Language Requirements (TOEFL iBT 94 with subscores / IELTS 7.0 with subscores / Cambridge 185; exemption countries) and Time Path (application + registration before 15 February; admission committee until end of March; eligible admitted candidates ranked mid-to-late April with online interviews; awards and notification at the beginning of May). This is the scheme record 144's previously stored URL actually pointed to before cleanup pass 108 recast that row as the Master Mind award it was titled as; Science@Leuven is catalogued here on its own terms as the Faculty of Science award. Award is NULL with basis 'variable' (award_amount NULL, EUR, 'year') because the Fund advertises an 'up to €12,000' ceiling and sets the exact amount per holder; deadline_date 2027-02-15 is the next annual closing (status 'upcoming': the fetched landing still showed the closed 2026-2027 round). min_ielts 7.0 stored (subscore detail in the requirements); min_gpa NULL. university_id set to the existing KU Leuven record (48) and a university_scholarships row added.$note$, 48, NULL, 'EUR', 'year', 'variable', NULL, 'Up to €12,000 for one academic year (exact amount set by the Science@Leuven Fund Board); continuation into the second master year conditional on outstanding results', 'The grant contributes toward study costs; it is not a formal tuition waiver, and the Faculty advises holders to bring extra money even when the full €12,000 is awarded.', 'Very strong English required: TOEFL iBT 94 overall (R19/L18/S19/W21), IELTS Academic 7.0 overall (R6.5/L6.0/S6.0/W6.0) or Cambridge Advanced/Proficiency 185; exemption only for degrees taught entirely in English in Australia, English-speaking Canada, Ireland, New Zealand, the UK or the USA.', $j$["Master's application via the KU Leuven Application Tool, registered on the scholarship website before 15 February", "Proof of an eligible non-Belgian bachelor's degree and excellent study results (transcripts; grading-system explanation if not in the transcript scan)", "English proficiency certificate at the scholarship minima (TOEFL iBT 94 / IELTS 7.0 / Cambridge 185) unless exempt", "Two reference letters from internationally renowned professors", "Motivation for the Faculty of Science master and willingness to act as a programme ambassador"]$j$, NULL, NULL, $json$[{"cycle": "2027-2028 entry", "deadline": "2027-02-15", "decisions": "2027-05", "status": "upcoming"}, {"pattern": "Annual: apply and register before 15 February; admission decisions through March, scholarship ranking and interviews in April, awards announced at the beginning of May"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (958, 'Doctoral Scholarships for Candidates from the Global South (Ghent University, BOF)', 'Ghent University (Special Research Fund, BOF)', 'Belgium', 'Sandwich PhD Scholarship (24 months in Ghent)', 0, 'Call 2027: joint proposals (candidate + Ghent University promoter + Global South supervisor) must be submitted in English to BOFapplication@ugent.be by 9 February 2027; requests for an exception to the funding/mobility scheme are due by 15 January 2027. Results are announced online from 12 May 2027, and the first Ghent research stay must start between 1 October 2027 and 28 February 2028.', '2027-02-09', 'fixed', NULL, NULL, $j$["PhD"]$j$, $j$["All"]$j$, $j$["Selected Global South countries per the official BOF country list (Uzbekistan is listed; the candidate must come from and hold the nationality of a listed country)"]$j$, NULL, NULL, false, true, $desc$Ghent University's Special Research Fund (Bijzonder Onderzoeksfonds, BOF) grants 15 PhD 'sandwich' scholarships a year to promising doctoral candidates from Global South countries who carry out half of their PhD research at Ghent University ('North') and the other half at a university in the Global South ('South'). Ghent University finances only its own part - a 24-month PhD scholarship in Ghent within a 48-month doctorate - while the other 24 months must be guaranteed by the partner institution in the South as a full-time local PhD scholarship or salary, with the candidate largely exempted from teaching (maximum 10% other tasks); this co-funding is mandatory, so the award is only for candidates whose home institution officially commits to its half in writing. The Ghent promoter additionally receives a bench fee of €310 per month of research in Ghent and an €8,000 travel budget. The mobility scheme is fixed: the doctorate starts and ends with a 3-12 month research stay in Ghent (first stay starting between 1 October 2027 and 28 February 2028 for call 2027), with at least 24 months of locally funded research in between; narrowly defined exceptions must be requested by 15 January 2027. Proposals are submitted jointly by the candidate, a Ghent University professor (whose support is indispensable) and a supervisor at the partner university, in any field of research with preference for topics relevant in a South-North context; only candidates intending to obtain a (joint) PhD degree at Ghent University qualify (exchange students cannot), the programme targets candidates near the start of their PhD (at least 36 months of doctoral research still to complete at the 1 October 2027 start), and the application deadline for call 2027 is 9 February 2027 with results from 12 May 2027. Uzbekistan appears on the official BOF country list (lower middle income column), so Uzbek nationals with a co-funding home institution and a willing Ghent promoter are eligible.$desc$, $req$Candidates must come from - and hold the nationality of - one of the selected Global South countries on the official BOF country list (Uzbekistan is included); only degree students intending to obtain a (joint) PhD at Ghent University can apply (no exchange students); at the fellowship start (1 October 2027) at least 36 months of doctoral research must remain. The proposal must be submitted jointly by the candidate, a Ghent University supervisor (ZAP) and a supervisor at the partner university/research centre in the Global South; without the Ghent professor's support the application is ineligible. Co-funding conditions to be guaranteed by the Southern partner: a local PhD supervisor; a written statement that the candidate receives a full-time local PhD scholarship or salary for 24 months of research in the South; and sufficient exemption from teaching or other assignments (maximum 10% of a full-time appointment). The mandatory mobility scheme (start and end in Ghent, first stay between 1 October 2027 and 28 February 2028, at least 24 months of Southern research in between) can only be excepted for documented curricular/fieldwork reasons approved before 15 January 2027. A Ghent supervisor may support at most two candidates per call, of different genders. No GPA or IELTS figure is published on the call page, so min_gpa/min_ielts are not recorded; applications and forms are in English.$req$, 'https://www.ugent.be/en/research/funding/bof/dos', 'https://www.ugent.be/en/research/funding/bof/dos', 'https://www.ugent.be/en/research/funding/bof/dos', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 15) from Ghent University's official 'Special Research Fund - Doctoral Scholarships for Candidates from the Global South - call 2027' page and its linked country-list PDF, both fetched the same day (15 sandwich PhDs annually; 24 months funded by Ghent within 48 months, mandatory 24-month full-time co-funding by the Southern partner with written guarantee and max 10% other tasks; bench fee €310/month of Ghent research plus €8,000 travel budget to the promoter; joint candidate/Ghent-promoter/South-supervisor proposals in English to BOFapplication@ugent.be by 9 February 2027; exception requests by 15 January 2027; results from 12 May 2027; first Ghent stay 1 October 2027-28 February 2028; at least 36 months of PhD remaining at start; (joint) UGent degree students only; gender-balance cap of two candidates per promoter). The fetched country list names Uzbekistan in its lower-middle-income column, confirming Uzbek eligibility first-hand; the restriction is recorded in eligible_countries as a category description rather than the full list. Award is NULL (EUR, 'month', 'variable'): the call page does not publish the monthly scholarship amount, so no figure is stored - the verifiable financial terms (24 scholarship months in Ghent, bench fee, travel budget, mandatory Southern co-funding) are stated in the text. deadline_date 2027-02-09 with status 'open' (the fetched page is the live call 2027). This record documents the BOF doctoral instrument on its own terms; the retired composite 410 had conflated it with the discontinued master's Top-up Grants. min_gpa/min_ielts NULL. university_id set to the existing Ghent University record (142) and a university_scholarships row added.$note$, 142, NULL, 'EUR', 'month', 'variable', NULL, '24-month PhD scholarship at Ghent University within a 48-month sandwich doctorate (monthly amount not published in the call) + €310/month bench fee and €8,000 travel budget to the Ghent promoter; 24 months of full-time co-funding by the Global South partner is mandatory', 'The Ghent half is funded as a PhD scholarship; enrolment/tuition handling follows Ghent University doctoral enrolment for the (joint) degree - the Southern 24 months must be funded by the partner institution.', 'Application forms are submitted in English; the call publishes no IELTS cutoff (English requirements follow the Ghent doctorate and the promoter''s assessment).', $j$["Support of a Ghent University professor (ZAP) as promoter - without it the application is ineligible - plus promoter's advice on the candidate and advice on the ethical/biosafety context", "Supervisor at a partner university/research centre in the Global South", "Written statement from the Southern partner guaranteeing a full-time local PhD scholarship or salary for 24 months and exemption from other assignments (max 10%)", "Joint application form in English submitted to BOFapplication@ugent.be by 9 February 2027", "Where needed: approved exception request on the funding/mobility scheme filed by 15 January 2027"]$j$, NULL, NULL, $json$[{"call": "2027", "exception_requests_by": "2027-01-15", "deadline": "2027-02-09", "results_from": "2027-05-12", "first_ghent_stay": "2027-10-01 to 2028-02-28", "status": "open"}, {"pattern": "Annual BOF call in autumn/winter for an autumn start: 48-month sandwich doctorate opening and closing with Ghent stays and at least 24 months of funded research in the South in between"}]$json$);

INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES
(3093, 'https://uclouvain.be/fr/facultes/epl/epl-excellence-scholarships-masters-programme', 'EPL Excellence Scholarships – Master''s programme - UCLouvain (official)', 'uclouvain.be', 'scholarship', now(), true, true, now()),
